mini_exercise.solution:
class Supresor:
    def __enter__(self):
        return self
    def __exit__(self, t, v, tb):
        return True

with Supresor():
    1 / 0
print("Sobrevivio")

from contextlib import contextmanager
@contextmanager
def demo():
    print("Inicio")
    try:
        yield
    finally:
        print("Fin")

with demo():
    print("Cuerpo")
